import turtle
import time
from 미로지도 import 지도들

turtle.tracer(0)
크기 = 30
판번호 = 0
지도 = 지도들[판번호]

def 가로(칸):
    return 칸 * 크기 - 210

def 세로(줄):
    return 135 - 줄 * 크기

붓 = turtle.Turtle()
붓.hideturtle()
붓.penup()

def 칸칠하기(줄, 칸, 색):
    붓.goto(가로(칸) - 15, 세로(줄) - 15)
    붓.color(색)
    붓.pendown()
    붓.begin_fill()
    for i in range(4):
        붓.forward(크기)
        붓.left(90)
    붓.end_fill()
    붓.penup()

색들 = {"#": "brown", "E": "green"}

class 보석:
    def __init__(self, 줄, 칸):
        self.줄 = 줄
        self.칸 = 칸
        self.몸 = turtle.Turtle()
        self.몸.shape("circle")
        self.몸.color("gold")
        self.몸.penup()
        self.몸.goto(가로(칸), 세로(줄))

보석들 = []

class 유령:
    def __init__(self, 줄, 칸):
        self.처음줄 = 줄
        self.처음칸 = 칸
        self.몸 = turtle.Turtle()
        self.몸.shape("square")
        self.몸.color("purple")
        self.몸.penup()
        self.처음으로()
    def 처음으로(self):
        self.줄 = self.처음줄
        self.칸 = self.처음칸
        self.보이기()
    def 보이기(self):
        self.몸.goto(가로(self.칸), 세로(self.줄))
    def 다가가기(self, 상대):
        if 상대.칸 > self.칸:
            self.칸 = self.칸 + 1
        elif 상대.칸 < self.칸:
            self.칸 = self.칸 - 1
        elif 상대.줄 > self.줄:
            self.줄 = self.줄 + 1
        elif 상대.줄 < self.줄:
            self.줄 = self.줄 - 1
        self.보이기()

유령들 = []

def 지도그리기():
    붓.clear()
    for 하나 in 유령들:
        하나.몸.hideturtle()
    유령들.clear()
    for 줄 in range(len(지도)):
        for 칸 in range(len(지도[줄])):
            글자 = 지도[줄][칸]
            if 글자 in 색들:
                칸칠하기(줄, 칸, 색들[글자])
            elif 글자 == "*":
                보석들.append(보석(줄, 칸))
            elif 글자 == "G":
                유령들.append(유령(줄, 칸))

지도그리기()

